"""Compensating transaction stack orchestrator."""

from typing import List
from action import ActionUnit
from context import WorkflowContext


class CompensatorEngine:
    def __init__(self):
        self._stack: List[ActionUnit] = []

    def register_executed(self, action: ActionUnit) -> None:
        self._stack.append(action)

    def compensate_all(self, ctx: WorkflowContext) -> None:
        # BUG: Compensates in FIFO insertion order instead of LIFO reverse stack order!
        while self._stack:
            action = self._stack.pop(0)  # BUG: pop(0) instead of pop()
            action.compensate_fn()
            ctx.compensated_actions.append(action.name)

